const emailData = $input.first().json;
const report = $('Validate & Normalize').first().json;
const esc = (s) => (s || '').replace(/'/g, "''");

// 先打印看结构
const raw = JSON.stringify(emailData);
const isApprove = emailData.approve === true || 
                  (emailData.data && emailData.data.approved === true) ||
                  (emailData.json && emailData.json.approved === true);
const action = isApprove ? 'approved' : 'rejected';

return {
  report_id: report.report_id,
  action: action,
  raw_email_output: raw,
  update_sql: "UPDATE experience_reports SET status = '" + action + "', reviewer_id = 'email-admin', review_comment = '', reviewed_at = NOW() WHERE id = '" + esc(report.report_id) + "'",
};

const row = $input.first().json;

// Handle Postgres result format (may be row object or rows array)
const report = row.rows ? row.rows[0] : row;

if (!report) {
  throw new Error('Report not found or not approved');
}

// Structure the experience as instructional knowledge
const structuredText = `【经验案例】
故障现象：${report.fault_description}

解决方案：${report.solution}

适用机型：${report.machine_type || '通用'}

提交人ID：${report.user_id}
审核状态：已审核通过

---
详细操作步骤：${report.solution}`;

return {
  report_id: report.id,
  title: report.title,
  user_id: report.user_id,
  machine_type: report.machine_type || '',
  full_text: structuredText,
  fault_description: report.fault_description,
  solution: report.solution,
  photos: report.photos || [],
  ingest_id: 'exp_' + report.id,
};

const result = $input.first().json;
const chunks = result.chunks || [];
const expData = $('Merge OCR Results').first().json;

return chunks.map(chunk => ({
  chunk_index: chunk.chunk_index,
  text: chunk.text,
  ingest_id: expData.ingest_id,
  report_id: expData.report_id,
  title: expData.title,
  machine_type: expData.machine_type,
  user_id: expData.user_id,
  source_files: expData.source_files || [],
}));

// Batch embed all chunk texts
const items = $input.all();
const texts = items.map(item => item.json.text);

return {
  texts,
  item_count: items.length,
  ingest_id: items[0]?.json?.ingest_id,
  report_id: items[0]?.json?.report_id,
  title: items[0]?.json?.title,
  source_files: items[0]?.json?.source_files || [],
  machine_type: items[0]?.json?.machine_type,
  user_id: items[0]?.json?.user_id,
};

function uuid4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}
// Assemble Qdrant points with experience metadata
const embedResult = $input.first().json;
const embeddings = embedResult.embeddings || [];
const chunkItems = $('Prepare Items').all();
const meta = $('Build Embed Batch').first().json;

const points = chunkItems.map((item, i) => ({
  id: uuid4(),
  vector: embeddings[i] || [],
  payload: {
    doc_type: 'experience',
    machine_type: item.json.machine_type,
    category: 'troubleshooting',
    chunk_text: item.json.text,
    chunk_index: item.json.chunk_index,
    source_title: item.json.title,
    source_file: item.json.source_files?.[0] || '',
    report_id: item.json.report_id,
    submitted_by: item.json.user_id,
    ingest_id: item.json.ingest_id,
    created_at: new Date().toISOString(),
  }
}));

return {
  points,
  point_count: points.length,
  report_id: meta.report_id,
  title: meta.title,
};

const data = $('Process Review').first().json;
const esc = (s) => (s || '').replace(/'/g, "''");
return {
  ...data,
  sql: "SELECT id, user_id, title, fault_description, solution, photos, machine_type FROM experience_reports WHERE id = '" + esc(data.report_id) + "' AND status = 'approved'"
};

// Build final response
const meta = $('Assemble Qdrant Points').first().json;

return {
  status: 'ok',
  message: '经验知识已入库',
  report_id: meta.report_id,
  title: meta.title,
  chunk_count: meta.point_count,
};

const report = $input.first().json;
let photosRaw = report.photos || [];
let photos = [];
if (typeof photosRaw === 'string') {
  try { photos = JSON.parse(photosRaw); } catch(e) { photos = []; }
} else if (Array.isArray(photosRaw)) {
  photos = photosRaw;
}

if (photos.length === 0) {
  return [{
    json: {
      ...report,
      ocr_texts: [],
      source_files: [],
      full_text: report.full_text,
    }
  }];
}

return photos.map((p, i) => ({
  json: {
    ...report,
    photo_index: i,
    photo_name: p.name || ('photo' + i + '.jpg'),
  },
  binary: {
    file: {
      data: (p.data || '').includes(',') ? (p.data || '').split(',')[1] : (p.data || ''),
      mimeType: 'image/' + ((p.name || 'jpg').split('.').pop()),
      fileName: p.name || ('photo' + i + '.jpg'),
    }
  }
}));

const report = $('Structure Experience').first().json;
const allOcr = $input.all().map(item => item.json);
const ocrTexts = allOcr.map(o => o.text || '').filter(t => t);
const sourceFiles = allOcr.map(o => o.file_path || '').filter(f => f);

return {
  ...report,
  full_text: report.full_text + (ocrTexts.length > 0 ? '\n\n[图片内容]\n' + ocrTexts.join('\n') : ''),
  source_files: sourceFiles,
};
